int vl53l0x_init(void){++init_calls;memset(&init_diag,0,sizeof init_diag);init_diag.result=mock_init_rc;init_diag.stage=mock_init_rc?3u:16u;init_diag.api_status=mock_init_rc?-4:0;init_diag.io_error=mock_init_rc?1:0;memset(&runtime_diag,0,sizeof runtime_diag);runtime_diag.last_return=mock_init_rc?-1:-2;runtime_diag.range_status=255;runtime_diag.raw_mm=-1;return mock_init_rc;}
