static void setup(uint64_t start,int init_rc){mock_now_ms=start;init_calls=read_calls=beep_calls=0;mock_init_rc=init_rc;mock_read_rc=-2;mock_mm=250;mock_status=0;mock_signal=65536u;mock_ambient=2u*65536u;led_color=WS_GREEN;led_bright=20;led_mode=WS_MODE_ALLON;collision_service_init();CHECK(init_calls==1&&read_calls==0);}
static int poll_at(uint64_t now){mock_now_ms=now;return collision_service_poll();}
static collision_service_diagnostic_t snapshot(void){collision_service_diagnostic_t d;unsigned ni=init_calls,nr=read_calls;collision_service_get_diagnostic(NULL);collision_service_get_diagnostic(&d);CHECK(ni==init_calls&&nr==read_calls);return d;}
static void optical_invalid(void){collision_service_diagnostic_t d;unsigned i;setup(0,0);mock_read_rc=-3;mock_status=2;mock_mm=8191;mock_signal=0;mock_ambient=9u*65536u;for(i=0;i<150;++i){(void)poll_at((uint64_t)i*200u);CHECK(!collision_service_state()->valid);CHECK(collision_service_state()->level==COLLISION_UNKNOWN);}d=snapshot();CHECK(d.poll_count==150&&d.frame_count==150);CHECK(d.invalid_count==150&&d.valid_count==0);CHECK(d.range_status==2&&d.raw_mm==8191);CHECK(d.signal_mcps_x65536==0&&d.ambient_mcps_x65536==9u*65536u);CHECK(d.recovery_count==0&&!d.recovery_pending&&init_calls==1);CHECK(d.valid_age_ms==UINT32_MAX&&d.frame_age_ms==0);mock_status=4;mock_mm=8190;(void)poll_at(30000);d=snapshot();CHECK(d.raw_mm==8190&&d.range_status==4&&d.frame_count==151);CHECK(d.recovery_count==0&&!d.recovery_pending&&init_calls==1);mock_read_rc=0;mock_status=0;mock_mm=8191;(void)poll_at(30200);d=snapshot();CHECK(!collision_service_state()->valid&&d.valid_count==0);CHECK(d.invalid_count==152&&d.frame_count==152);CHECK(d.recovery_count==0&&init_calls==1);CHECK(beep_calls==0);puts("PASS optical invalid is never a valid distance and never restarts");}
static void startup_failure(void){collision_service_diagnostic_t d;setup(0,-4);d=snapshot();CHECK(!d.ready&&d.recovery_pending&&d.recovery_reason==COLLISION_RECOVERY_INIT);CHECK(d.init_failure_count==1&&d.retry_in_ms==1000);CHECK(d.poll_age_ms==UINT32_MAX&&d.frame_age_ms==UINT32_MAX&&d.valid_age_ms==UINT32_MAX);(void)poll_at(999);d=snapshot();CHECK(init_calls==1&&read_calls==0&&d.retry_in_ms==1);(void)poll_at(1000);d=snapshot();CHECK(init_calls==2&&d.recovery_count==1&&d.init_failure_count==2);CHECK(d.recovery_pending&&d.retry_in_ms==2000&&!d.ready);(void)poll_at(2999);d=snapshot();CHECK(init_calls==2&&d.retry_in_ms==1);mock_init_rc=0;(void)poll_at(3000);d=snapshot();CHECK(init_calls==3&&d.recovery_count==2&&d.ready&&!d.recovery_pending);CHECK(d.last_init_result==0&&d.valid_count==0);mock_read_rc=0;mock_status=0;mock_mm=250;(void)poll_at(3001);d=snapshot();CHECK(collision_service_state()->valid&&collision_service_state()->distance_mm==250);CHECK(d.frame_count==1&&d.valid_count==1&&d.valid_age_ms==0);puts("PASS startup failure backoff");}
static void no_frame(void){collision_service_diagnostic_t d;unsigned i;setup(0,0);for(i=0;i<10;++i)(void)poll_at((uint64_t)i*200u);d=snapshot();CHECK(!d.recovery_pending&&init_calls==1);(void)poll_at(2000);d=snapshot();CHECK(d.recovery_pending&&d.recovery_reason==COLLISION_RECOVERY_NO_FRAME);CHECK(d.retry_in_ms==1000&&d.frame_count==0&&d.not_ready_count==11);(void)poll_at(2999);d=snapshot();CHECK(init_calls==1&&d.retry_in_ms==1);(void)poll_at(3000);d=snapshot();CHECK(init_calls==2&&d.recovery_count==1&&d.ready&&!d.recovery_pending);CHECK(d.frame_count==0&&d.valid_count==0);setup(0,0);for(i=0;i<=10;++i)(void)poll_at((uint64_t)i*200u);d=snapshot();CHECK(d.recovery_pending);mock_read_rc=-3;mock_status=4;mock_mm=8190;(void)poll_at(2200);d=snapshot();CHECK(!d.recovery_pending&&d.recovery_reason==COLLISION_RECOVERY_NONE);CHECK(d.frame_count==1&&d.valid_count==0&&d.invalid_count==1);(void)poll_at(3000);d=snapshot();CHECK(init_calls==1&&d.recovery_count==0&&d.frame_count==2);puts("PASS no frame watchdog and cancellation");}
static void io_streak(void){collision_service_diagnostic_t d;setup(0,0);mock_read_rc=-4;(void)poll_at(0);(void)poll_at(200);d=snapshot();CHECK(d.io_error_count==2&&!d.recovery_pending);(void)poll_at(400);d=snapshot();CHECK(d.io_error_count==3&&d.recovery_pending&&d.retry_in_ms==1000);CHECK(d.recovery_reason==COLLISION_RECOVERY_IO);CHECK(d.last_return==-4&&d.last_api_status==-20&&d.last_io_error==1);mock_read_rc=-2;(void)poll_at(600);d=snapshot();CHECK(!d.recovery_pending&&d.not_ready_count==1&&init_calls==1);mock_read_rc=-4;(void)poll_at(800);(void)poll_at(1000);(void)poll_at(1200);d=snapshot();CHECK(d.recovery_pending&&d.recovery_reason==COLLISION_RECOVERY_IO);CHECK(d.retry_in_ms==1000);(void)poll_at(2199);d=snapshot();CHECK(init_calls==1&&d.retry_in_ms==1);(void)poll_at(2200);d=snapshot();CHECK(init_calls==2&&d.recovery_count==1&&d.ready&&!d.recovery_pending);mock_read_rc=-3;mock_status=2;mock_mm=8191;(void)poll_at(2201);d=snapshot();CHECK(d.frame_count==1&&d.invalid_count==1&&d.valid_count==0);CHECK(!d.recovery_pending&&!collision_service_state()->valid);puts("PASS IO streak recovery and healthy cancellation");}
static void stale_and_wrap(void){collision_service_diagnostic_t d;const uint64_t start=(uint64_t)UINT32_MAX-250u;setup(0,0);mock_read_rc=0;mock_status=0;mock_mm=250;(void)poll_at(0);CHECK(collision_service_state()->valid&&collision_service_state()->level==COLLISION_DANGER);CHECK(led_color==WS_RED&&led_bright==55&&led_mode==WS_MODE_ALLON&&beep_calls>0);mock_read_rc=-2;(void)poll_at(200);(void)poll_at(400);(void)poll_at(600);(void)poll_at(700);CHECK(collision_service_state()->valid);CHECK(poll_at(701)==1);d=snapshot();CHECK(!collision_service_state()->valid&&collision_service_state()->level==COLLISION_UNKNOWN);CHECK(led_color==WS_GREEN&&led_bright==20&&led_mode==WS_MODE_ALLON);CHECK(d.valid_age_ms==701&&d.frame_age_ms==701&&!d.recovery_pending);setup(start,0);mock_read_rc=0;mock_status=0;mock_mm=250;(void)poll_at(start);mock_read_rc=-2;(void)poll_at(start+700u);CHECK(collision_service_state()->valid);(void)poll_at(start+701u);d=snapshot();CHECK(!collision_service_state()->valid&&d.valid_age_ms==701);CHECK(led_color==WS_GREEN&&led_bright==20&&led_mode==WS_MODE_ALLON);(void)poll_at(start+2000u);d=snapshot();CHECK(d.recovery_pending&&d.retry_in_ms==1000);CHECK(d.recovery_reason==COLLISION_RECOVERY_NO_FRAME);(void)poll_at(start+2999u);d=snapshot();CHECK(init_calls==1&&d.retry_in_ms==1);(void)poll_at(start+3000u);d=snapshot();CHECK(init_calls==2&&d.recovery_count==1&&d.ready);puts("PASS stale LED restoration and time wrap");}
